{"source": {"path": "data/s101_feature_catalogue_v2_parsed.json", "sha256": "0d26c66d0e1afd8a6ae33629e9bc1bb929c6a3735ccd1d60f637d149a54cad37", "locator": "features/Landmark", "product": "S-101", "version": "2.0.0"}, "record": {"code": "Landmark", "definition": "Any prominent object at a fixed location on land which can be used in determining a location or a direction.", "permitted_primitives": ["point", "curve", "surface"]}}
{"source": {"path": "data/s101_feature_catalogue_v2_parsed.json", "sha256": "0d26c66d0e1afd8a6ae33629e9bc1bb929c6a3735ccd1d60f637d149a54cad37", "locator": "features/LightAllAround", "product": "S-101", "version": "2.0.0"}, "record": {"code": "LightAllAround", "definition": "An all around light is a light that is visible over the whole horizon of interest to marine navigation and having no change in the characteristics of the light.", "permitted_primitives": ["point"]}}
{"source": {"path": "data/s101_feature_catalogue_v2_parsed.json", "sha256": "0d26c66d0e1afd8a6ae33629e9bc1bb929c6a3735ccd1d60f637d149a54cad37", "locator": "features/LightSectored", "product": "S-101", "version": "2.0.0"}, "record": {"code": "LightSectored", "definition": "A light presenting different appearances (in particular, different colours) over various parts of the horizon of interest to maritime navigation.", "permitted_primitives": ["point"]}}
{"source": {"path": "data/s101_feature_catalogue_v2_parsed.json", "sha256": "0d26c66d0e1afd8a6ae33629e9bc1bb929c6a3735ccd1d60f637d149a54cad37", "locator": "features/LateralBuoy", "product": "S-101", "version": "2.0.0"}, "record": {"code": "LateralBuoy", "definition": "A lateral buoy is used to indicate the port or starboard hand side of the route to be followed. They are generally used for well-defined channels and are used in conjunction with a conventional direction of buoyage.", "permitted_primitives": ["point"]}}
{"source": {"path": "data/s101_feature_catalogue_v2_parsed.json", "sha256": "0d26c66d0e1afd8a6ae33629e9bc1bb929c6a3735ccd1d60f637d149a54cad37", "locator": "features/CardinalBuoy", "product": "S-101", "version": "2.0.0"}, "record": {"code": "CardinalBuoy", "definition": "A cardinal buoy is used in conjunction with the compass to indicate where the mariner may find the best navigable water. It is placed in one of the four quadrants (North, East, South and West), bounded by inter-cardinal bearings from the point marked.", "permitted_primitives": ["point"]}}
{"source": {"path": "data/s101_feature_catalogue_v2_parsed.json", "sha256": "0d26c66d0e1afd8a6ae33629e9bc1bb929c6a3735ccd1d60f637d149a54cad37", "locator": "features/IsolatedDangerBuoy", "product": "S-101", "version": "2.0.0"}, "record": {"code": "IsolatedDangerBuoy", "definition": "An isolated danger buoy is a buoy moored on or above an isolated danger of limited extent, which has navigable water all around it.", "permitted_primitives": ["point"]}}
{"source": {"path": "data/s101_feature_catalogue_v2_parsed.json", "sha256": "0d26c66d0e1afd8a6ae33629e9bc1bb929c6a3735ccd1d60f637d149a54cad37", "locator": "features/SafeWaterBuoy", "product": "S-101", "version": "2.0.0"}, "record": {"code": "SafeWaterBuoy", "definition": "A safe water buoy is used to indicate that there is navigable water around the mark.", "permitted_primitives": ["point"]}}
{"source": {"path": "data/s101_feature_catalogue_v2_parsed.json", "sha256": "0d26c66d0e1afd8a6ae33629e9bc1bb929c6a3735ccd1d60f637d149a54cad37", "locator": "features/SpecialPurposeGeneralBuoy", "product": "S-101", "version": "2.0.0"}, "record": {"code": "SpecialPurposeGeneralBuoy", "definition": "A special purpose buoy is primarily used to indicate an area or feature, the nature of which is apparent from reference to a chart, Sailing Directions or Notices to Mariners.", "permitted_primitives": ["point"]}}
{"source": {"path": "data/s101_feature_catalogue_v2_parsed.json", "sha256": "0d26c66d0e1afd8a6ae33629e9bc1bb929c6a3735ccd1d60f637d149a54cad37", "locator": "features/EmergencyWreckMarkingBuoy", "product": "S-101", "version": "2.0.0"}, "record": {"code": "EmergencyWreckMarkingBuoy", "definition": "An emergency wreck marking buoy is a buoy moored on or above a new wreck, designed to provide a prominent (both visual and radio) and easily identifiable temporary first response.", "permitted_primitives": ["point"]}}
{"source": {"path": "data/s101_feature_catalogue_v2_parsed.json", "sha256": "0d26c66d0e1afd8a6ae33629e9bc1bb929c6a3735ccd1d60f637d149a54cad37", "locator": "features/InstallationBuoy", "product": "S-101", "version": "2.0.0"}, "record": {"code": "InstallationBuoy", "definition": "An installation buoy is a buoy used for loading tankers with gas or oil.", "permitted_primitives": ["point"]}}
{"source": {"path": "data/s101_feature_catalogue_v2_parsed.json", "sha256": "0d26c66d0e1afd8a6ae33629e9bc1bb929c6a3735ccd1d60f637d149a54cad37", "locator": "features/MooringBuoy", "product": "S-101", "version": "2.0.0"}, "record": {"code": "MooringBuoy", "definition": "A buoy secured to the bottom by permanent moorings with means for mooring a vessel by use of its anchor chain or mooring lines.", "permitted_primitives": ["point"]}}

